import{_ as e,o as a,c as r,a3 as i}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Completar número do processo CNJ automaticamente","description":"","frontmatter":{"title":"Completar número do processo CNJ automaticamente","id":"eproc-autocomplete-cnj","plataforma":"eproc","grupo":"Pesquisa e filtros","plano":"free","desde":"1.0.2","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-autocomplete-cnj.md","filePath":"funcionalidades/eproc-autocomplete-cnj.md"}'),t={name:"funcionalidades/eproc-autocomplete-cnj.md"};function s(c,o,n,d,m,p){return a(),r("div",null,o[0]||(o[0]=[i('<h1 id="completar-numero-do-processo-cnj-automaticamente" tabindex="-1">Completar número do processo CNJ automaticamente <a class="header-anchor" href="#completar-numero-do-processo-cnj-automaticamente" aria-label="Permalink to &quot;Completar número do processo CNJ automaticamente&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No campo de pesquisa rápida do menu lateral, completa o número do processo enquanto você digita: basta o número principal e o dígito verificador para o eploc descobrir o ano e acrescentar o final do número (o sufixo do tribunal e da comarca). Se você só lembra o número e o ano, digite-os separados por barra e o eploc calcula o dígito verificador.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, campo de pesquisa rápida do menu lateral.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><p><strong>Com número e dígito verificador</strong></p><ol><li>Digite os 9 primeiros dígitos (por exemplo, <code>000012345</code>, ou <code>0000123-45</code>).</li><li>O eploc acha o ano que combina com o dígito verificador e completa o número no formato <code>NNNNNNN-DD.AAAA.J.TR.OOOO</code>, com o ano e o sufixo configurado.</li><li>Se você digitar os 13 primeiros dígitos (com o ano), o número também é completado com o sufixo.</li></ol><p><strong>Com número e ano</strong></p><ol><li>Digite o número principal, uma barra e o ano: <code>1000713/2026</code> ou <code>1000713/26</code>.</li><li>O eploc mostra uma sugestão com o número completo. Confirme com um clique, Tab ou Enter. Enter já pesquisa o número.</li></ol><p><strong>Sufixo</strong></p><p>Na primeira vez, o eploc tenta descobrir o sufixo (por exemplo <code>.8.13.0242</code>) nos números de processo que aparecem nas telas do eproc. Se não conseguir, pede que você o informe numa janela.</p><p>Com a <a href="./eproc-pesquisa-rapida-avancada">Pesquisa rápida por nome ou CPF/CNPJ</a> ligada, CPFs e CNPJs válidos digitados no campo também são formatados automaticamente.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Sufixo final (ex.: .8.13.0242)</td><td>vazio</td><td>Final do número usado para completar. Em branco, é detectado automaticamente ou pedido na primeira vez.</td></tr></tbody></table><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O ano é deduzido pelo dígito verificador para processos de 2009 em diante. Se nenhum ano combinar, o número não é completado e você precisa digitar o ano.</li><li>Na forma &quot;número/ano&quot;, o eploc sempre calcula um dígito verificador. Por isso ele só sugere o número e espera sua confirmação: um ano digitado errado levaria a um processo errado.</li><li>O sufixo é um só. Quem pesquisa processos de várias comarcas precisa digitar o número completo dos que não são da comarca configurada.</li><li>Números inválidos são sinalizados no campo.</li></ul>',17)]))}const f=e(t,[["render",s]]);export{u as __pageData,f as default};
